import numpy as np, h5py, scipy.io as sio, os

def is_v73(fn):
    with open(fn,'rb') as f: return b'MATLAB 7.3' in f.read(128)

class H5Obj:
    """minimal wrapper for v7.3 obj"""
    def __init__(self,f,ref):
        self.f=f; self.g=f[ref] if isinstance(ref,h5py.Reference) else ref

def deref(f,x):
    return f[x] if isinstance(x,h5py.Reference) else x

def arr(f,ds):
    return np.array(ds)

def load_bp(fn):
    """return dict of bp fields common to both formats"""
    out={}
    if is_v73(fn):
        f=h5py.File(fn,'r'); o=f['obj']; bp=o['bp']
        g=lambda k: np.array(bp[k]).ravel()
        out['Ntrials']=int(np.array(bp['Ntrials']).ravel()[0])
        for k in ['hit','miss','no','early','autowater','R','L']:
            out[k]=g(k)
        out['stim']=np.array(bp['stim']['enable']).ravel()
        for k in ['goCue','sample','delay','bitStart','reward']:
            out[k]=np.array(bp['ev'][k]).ravel()
        f.close()
    else:
        m=sio.loadmat(fn,squeeze_me=True,struct_as_record=False)
        o=m['obj']; bp=o.bp
        out['Ntrials']=int(bp.Ntrials)
        for k in ['hit','miss','no','early','autowater','R','L']:
            out[k]=np.atleast_1d(getattr(bp,k)).astype(float)
        out['stim']=np.atleast_1d(bp.stim.enable).astype(float)
        for k in ['goCue','sample','delay','bitStart','reward']:
            out[k]=np.atleast_1d(getattr(bp.ev,k)).astype(float)
    return out
EOF
