import sys; sys.path.insert(0,'/tmp')
from parse_meta import sessions, avail
from loader import load_bp
import numpy as np
for s in sessions:
    k=(s['anm'],s['date'])
    if k not in avail: continue
    bp=load_bp(avail[k])
    aw=bp['autowater']>0; e=bp['early']>0; st=bp['stim']>0
    use=(~e)&(~st)
    print(f"{k[0]:6s} {k[1]} N={bp['Ntrials']:4d} use={use.sum():4d} WC={int((aw&use).sum()):4d} DR={int(((~aw)&use).sum()):4d} hit={int(bp['hit'][use].sum()):4d} miss={int(bp['miss'][use].sum()):4d} no={int(bp['no'][use].sum()):4d} " + ('RD' if 'Randomized' in avail[k] else 'EP'))
